export const html=`<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>وستا | حسابداری</title><link href="/style.css" rel="stylesheet"><script src="/app.js" defer></script></head><body><div id="login" class="login"><div class="login-art"><span class="logo">V</span><div class="art-text"><p class="art-eyebrow">VESTA ACCOUNTING · فضای مالی شما</p><h1>وستا،<br>با دید روشن‌تر.</h1><p>فروش، موجودی و حسابداری؛ در یک محیط منظم و مستقل.</p><div class="art-metrics"><div><b>۲</b><span>طرف هر سند مالی</span></div><div><b>↔</b><span>ثبت و تطبیق مستند</span></div></div></div><small>حریم داده‌ها · بدون تغییر در فروشگاه</small></div><form id="loginForm" class="login-card"><span class="tiny">VESTA / ACCOUNTING</span><h2>خوش آمدید</h2><p class="muted">برای ورود به فضای کاری خود، نام کاربری و رمز عبور را وارد کنید.</p><label>نام کاربری<input name="username" autocomplete="username" required></label><label>رمز عبور<input name="password" type="password" autocomplete="current-password" required></label><button class="primary" type="submit">ورود به پنل ←</button><p id="loginError" role="alert" class="error"></p><div class="hint">MODE_LOGIN_LABEL · FONT_LABEL</div></form></div><div id="app" hidden><aside id="sidebar"><div class="brand"><span class="logo">V</span><div><strong>وستا</strong><small>فضای کاری مالی</small></div></div><nav id="nav" aria-label="منوی اصلی"></nav><div class="sidebar-bottom"><span class="dot"></span><div><b id="userName">کاربر</b><small id="sidebarMode">MODE_SHORT_LABEL</small></div><button id="logout" title="خروج">↪</button></div></aside><main><header class="top"><div class="top-title"><button id="menu" aria-label="منو">☰</button><div><span class="tiny">فضای کاری وستا</span><h1 id="title">داشبورد</h1></div></div><div class="top-actions"><span class="badge demo"><i></i><span id="modeBadge">MODE_SHORT_LABEL</span></span><span id="today" class="muted"></span></div></header><div class="notice" id="modeNotice"><b>MODE_SHORT_LABEL</b> · MODE_NOTICE_LABEL</div><div id="message" role="status" aria-live="polite"></div><div id="content"></div><footer>VESTA ACCOUNTING <span>· تومان · FONT_LABEL</span></footer></main></div><div id="overlay" hidden></div><section id="detail" class="drawer" role="dialog" aria-modal="true" aria-label="جزئیات" hidden><div class="drawer-head"><h2 id="drawerTitle">جزئیات</h2><button id="closeDrawer" aria-label="بستن">×</button></div><div id="drawerBody"></div></section><noscript>برای کار با سامانه جاوااسکریپت را فعال کنید.</noscript></body></html>`;

