  async function api(path,method='GET',data){const h={Accept:'application/json'};if(method!=='GET'){h['Content-Type']='application/json';if(csrf)h['X-CSRF-Token']=csrf;}const r=await fetch('/api'+path,{method,headers:h,credentials:'same-origin',...(data?{body:JSON.stringify(data)}:{})});const d=await r.json();if(!r.ok){if(r.status===401&&path!=='/login'){leave();}throw Error(d.error||'خطا در دریافت اطلاعات');}return d;}
