  function excel(rows,columns){
    const workbook=reportWorkbook(rows,columns,k=>labels[k]||k,(k,value)=>{
      if(value==null)return {value:null};
      const raw=String(value);
      if(moneyFields.has(k)||monetaryFields.includes(k)||typeof value==='number'){
        // Excel stores at most 15 significant digits. Keep larger exact values as text.
        const numeric=/^-?[0-9]+(?:[.][0-9]+)?$/.test(raw)&&raw.replace(/[^0-9]/g,'').length<=15;
        return {value:raw,numeric};
      }
      if(dateFields.includes(k))return {value:jalali(value)};
      if(k==='kind')return {value:kindFa[value]||value};
      return {value:reviewLabels[value]||value};
    });
    const link=el('a');link.href=URL.createObjectURL(workbook);link.download='vesta-'+current+'.xlsx';
    link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);
  }
