  async function go(m,account){const seq=++sequence;current=m;$('title').textContent=names[m]||m;$('sidebar').classList.remove('open');for(const btn of $('nav').querySelectorAll('button'))btn.classList.toggle('active',btn.dataset.view===m);$('content').replaceChildren(el('p','در حال بارگذاری…','muted'));msg('');try{const nodes=m==='dashboard'?await dashboard():await moduleView(m,account);if(seq===sequence)$('content').replaceChildren(...nodes);}catch(e){if(seq===sequence)$('content').replaceChildren(el('div',e.message,'panel error'));}}
  async function enter(user){csrf=user.csrf;role=user.role;mode=user.mode||'demo';opts=await api('/options');$('userName').textContent=user.username+' · '+(role==='owner'?'مالک':'بازبین');if(mode==='source'&&!$('nav').querySelector('[data-view="source_products"]')){const group=el('div','داده خام ووکامرس','nav-group');$('nav').prepend(group);let after=group;for(const [view,icon,title] of sourceNav){const b=button('',()=>go(view),'nav-btn');b.dataset.view=view;b.append(el('span',icon),el('span',title));after.after(b);after=b;}}$('login').hidden=true;$('app').hidden=false;$('today').textContent=jalali(new Date().toISOString());await go('dashboard');}
  for(const [label,items] of groups){$('nav').append(el('div',label,'nav-group'));for(const [view,icon,title] of items){const b=button('',()=>go(view),'nav-btn');b.dataset.view=view;b.append(el('span',icon),el('span',title));$('nav').append(b);}}
  $('loginForm').addEventListener('submit',async e=>{e.preventDefault();$('loginError').textContent='';const b=e.target.querySelector('button');b.disabled=true;try{const d=new FormData(e.target);await enter(await api('/login','POST',{username:d.get('username'),password:d.get('password'),otp:d.get('otp')}));e.target.reset();}catch(e){$('loginError').textContent=e.message;}finally{b.disabled=false;}});$('logout').addEventListener('click',async()=>{try{await api('/logout','POST',{});}finally{leave();}});$('menu').addEventListener('click',()=>$('sidebar').classList.toggle('open'));$('closeDrawer').addEventListener('click',closeDrawer);$('overlay').addEventListener('click',closeDrawer);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrawer();});api('/me').then(enter).catch(()=>{});
